import numpy as np
from scipy.optimize import minimize

def run_packing():
    n = 26
    # Initial guess: 5x5 grid + center circle
    centers = np.zeros((n, 2))
    for i in range(5):
        for j in range(5):
            idx = i * 5 + j
            centers[idx] = [i / 5.0, j / 5.0]
    centers[25] = [0.5, 0.5]
    radii = np.full(n, 0.05)
    x0 = np.concatenate([centers.reshape(n * 2), radii])

    def objective(x):
        x_flat = x.reshape(n, 3)
        return -np.sum(x_flat[:, 2])

    def constraint_x_ge_r_i(x, i):
        x_flat = x.reshape(n, 3)
        return x_flat[i, 0] - x_flat[i, 2]

    def constraint_x_le_1_minus_r_i(x, i):
        x_flat = x.reshape(n, 3)
        return 1 - x_flat[i, 0] - x_flat[i, 2]

    def constraint_y_ge_r_i(x, i):
        x_flat = x.reshape(n, 3)
        return x_flat[i, 1] - x_flat[i, 2]

    def constraint_y_le_1_minus_r_i(x, i):
        x_flat = x.reshape(n, 3)
        return 1 - x_flat[i, 1] - x_flat[i, 2]

    def constraint_pairwise(x, i, j):
        x_flat = x.reshape(n, 3)
        dx = x_flat[i, 0] - x_flat[j, 0]
        dy = x_flat[i, 1] - x_flat[j, 1]
        dr = x_flat[i, 2] + x_flat[j, 2]
        return dx**2 + dy**2 - dr**2

    constraints = []
    for i in range(n):
        constraints.append({'type': 'ineq', 'fun': lambda x, i=i: constraint_x_ge_r_i(x, i)})
        constraints.append({'type': 'ineq', 'fun': lambda x, i=i: constraint_x_le_1_minus_r_i(x, i)})
        constraints.append({'type': 'ineq', 'fun': lambda x, i=i: constraint_y_ge_r_i(x, i)})
        constraints.append({'type': 'ineq', 'fun': lambda x, i=i: constraint_y_le_1_minus_r_i(x, i)})
    for i in range(n):
        for j in range(i + 1, n):
            constraints.append({'type': 'ineq', 'fun': lambda x, i=i, j=j: constraint_pairwise(x, i, j)})

    result = minimize(objective, x0, constraints=constraints, method='SLSQP', tol=1e-6)
    if not result.success:
        return (centers, radii, 0.0)
    optimized_x = result.x
    optimized_x_flat = optimized_x.reshape(n, 3)
    centers_opt = optimized_x_flat[:, :2]
    radii_opt = optimized_x_flat[:, 2]
    return (centers_opt, radii_opt, np.sum(radii_opt))
